import React from 'react';
import { getCurrentLogo } from './utils/logoUtils';
import {
  OnlyActionContainer,
  TwoActionsContainer,
  PageContainer,
  PageTitle,
  PageDescription,
  SectionContainer,
  SectionDescription,
} from './EmptyState.styles';
import { Button } from '../button';
import { EmptyPageTypes, EmptySectionTypes } from './EmptyState.types';

const PageLevel = ({
  title,
  description,
  actions,
  ilustrationName = 'beesAlert',
  customIlustration,
  ...props
}: EmptyPageTypes): JSX.Element => {
  const onlyAction = actions && actions.length === 1 ? actions[0] : null;
  const twoActions = actions && actions.length === 2;
  return (
    <PageContainer {...props}>
      {customIlustration ? (
        <img
          src={customIlustration?.src}
          alt={customIlustration?.alt}
          width={customIlustration?.width}
          height={customIlustration?.height}
        />
      ) : (
        <img src={getCurrentLogo(ilustrationName).src} alt={getCurrentLogo(ilustrationName).alt} />
      )}
      {title && <PageTitle>{title}</PageTitle>}
      {description && <PageDescription>{description}</PageDescription>}

      {onlyAction && (
        <OnlyActionContainer>
          <Button
            key={onlyAction.name}
            type="button"
            onClick={onlyAction.action}
            variant={onlyAction?.variant}
          >
            {onlyAction.name}
          </Button>
        </OnlyActionContainer>
      )}
      {twoActions && (
        <TwoActionsContainer>
          {actions.map((action) => (
            <Button
              key={action?.name}
              type="button"
              onClick={action?.action}
              variant={action?.variant}
            >
              {action?.name}
            </Button>
          ))}
        </TwoActionsContainer>
      )}
    </PageContainer>
  );
};

const SectionLevel = ({
  description,
  customIlustration,
  ilustrationName = 'beesAlert',
  ...props
}: EmptySectionTypes): JSX.Element => (
  <SectionContainer {...props}>
    {customIlustration ? (
      <img
        src={customIlustration?.src}
        alt={customIlustration?.alt}
        width={customIlustration?.width}
        height={customIlustration?.height}
      />
    ) : (
      <img src={getCurrentLogo(ilustrationName).src} alt={getCurrentLogo(ilustrationName).alt} />
    )}
    {description && <SectionDescription>{description}</SectionDescription>}
  </SectionContainer>
);

export { PageLevel, SectionLevel };
